///   arg1: [[0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0xff], [0x0 ~> 0x3]]
pub fn fromBytes(out1: *TightFieldElement, arg1: [17]u8) void {
    @setRuntimeSafety(mode == .debug);

    const x1: u32 = (@as(u32, arg1[16]) << 24);
    const x2: u32 = (@as(u32, arg1[15]) << 16);
    const x3: u32 = (@as(u32, arg1[14]) << 8);
    const x4: u8 = arg1[13];
    const x5: u32 = (@as(u32, arg1[12]) << 18);
    const x6: u32 = (@as(u32, arg1[11]) << 10);
    const x7: u32 = (@as(u32, arg1[10]) << 2);
    const x8: u32 = (@as(u32, arg1[9]) << 20);
    const x9: u32 = (@as(u32, arg1[8]) << 12);
    const x10: u32 = (@as(u32, arg1[7]) << 4);
    const x11: u32 = (@as(u32, arg1[6]) << 22);
    const x12: u32 = (@as(u32, arg1[5]) << 14);
    const x13: u32 = (@as(u32, arg1[4]) << 6);
    const x14: u32 = (@as(u32, arg1[3]) << 24);
    const x15: u32 = (@as(u32, arg1[2]) << 16);
    const x16: u32 = (@as(u32, arg1[1]) << 8);
    const x17: u8 = arg1[0];
    const x18: u32 = (x16 + x17);
    const x19: u32 = (x15 + x18);
    const x20: u32 = (x14 + x19);
    const x21: u32 = (x20 & 0x3ffffff);
    const x22: u8 = @truncate((x20 >> 26));
    const x23: u32 = (x13 + x22);
    const x24: u32 = (x12 + x23);
    const x25: u32 = (x11 + x24);
    const x26: u32 = (x25 & 0x3ffffff);
    const x27: u8 = @truncate((x25 >> 26));
    const x28: u32 = (x10 + x27);
    const x29: u32 = (x9 + x28);
    const x30: u32 = (x8 + x29);
    const x31: u32 = (x30 & 0x3ffffff);
    const x32: u8 = @truncate((x30 >> 26));
    const x33: u32 = (x7 + x32);
    const x34: u32 = (x6 + x33);
    const x35: u32 = (x5 + x34);
    const x36: u32 = (x3 + x4);
    const x37: u32 = (x2 + x36);
    const x38: u32 = (x1 + x37);
    out1[0] = x21;
    out1[1] = x26;
    out1[2] = x31;
    out1[3] = x35;
    out1[4] = x38;
}

/// The function relax is the identity function converting from tight field elements to loose field elements.
///
/// Postconditions:
///   out1 = arg1
///
pub fn relax(out1: *LooseFieldElement, arg1: TightFieldElement) void {
    @setRuntimeSafety(mode == .debug);

    const x1: u32 = arg1[0];
    const x2: u32 = arg1[1];
    const x3: u32 = arg1[2];
    const x4: u32 = arg1[3];
    const x5: u32 = arg1[4];
    out1[0] = x1;
    out1[1] = x2;
    out1[2] = x3;
    out1[3] = x4;
    out1[4] = x5;
}
